package com.networkmonitorpro.service; import android.app.*;import android.content.*;import android.os.*;import com.networkmonitorpro.data.repository.NotificationRepository;import com.networkmonitorpro.network.*; public class NetworkMonitorService extends Service{ NetworkDetector detector; String last=""; int lastSignal=0; NotificationRepository repo; public void onCreate(){super.onCreate(); repo=new NotificationRepository(this); startForeground(101,NotificationHelper.monitor(this,"Starting monitor")); detector=new NetworkDetector(this); detector.snapshots.observeForever(this::handle); detector.start();} private void handle(NetworkSnapshot s){startForeground(101,NotificationHelper.monitor(this,s.type+" • "+s.signalLevel+"% • "+(s.reachable?"Online":"Offline"))); if(!last.isEmpty()&&!last.equals(s.type)) notify("Network Switched",last+" → "+s.type,"NETWORK_SWITCHED"); if(s.type.startsWith("5G")) notify("5G Available",s.type+" network is available","5G"); if(s.type.startsWith("4G")) notify("4G Available",s.type+" network is available","4G"); if(s.type.equals("WiFi")) notify("WiFi Connected","Connected to WiFi","WIFI"); if(!s.reachable) notify("Internet Lost","Internet reachability check failed","LOST"); if(s.signalLevel<30&&lastSignal>=30) notify("Signal Weak","Signal dropped to "+s.signalLevel+"%","WEAK"); if(s.signalLevel>=60&&lastSignal<60) notify("Signal Improved","Signal improved to "+s.signalLevel+"%","IMPROVED"); last=s.type; lastSignal=s.signalLevel;} private void notify(String t,String m,String type){NotificationHelper.alert(this,t,m);repo.add(type,t,m);} public int onStartCommand(Intent i,int f,int id){return START_STICKY;} public IBinder onBind(Intent i){return null;} public void onDestroy(){if(detector!=null)detector.stop(); super.onDestroy();} }
